/* --- map geometry --- */
const P = (lo, la) => [(lo - 10.9) * 72, (52.7 - la) * 112];
const pts = a =>
  a
    .map(([lo, la]) =>
      P(lo, la)
        .map(v => v.toFixed(1))
        .join(","),
    )
    .join(" ");
